(function () {
  "use strict";

  var catalogue = window.T6_COURSES || {};

  function rotateOptions(correct, wrong, shift) {
    var values = [correct].concat(wrong).slice(0, 4);
    var amount = ((shift % values.length) + values.length) % values.length;
    var options = values.slice(amount).concat(values.slice(0, amount));
    return {options: options, answer: options.indexOf(correct)};
  }

  /* Label every option in a set with the concept under test (CONTENT-RULES R3).
   *
   * `explain` and `apply` were never guilty of the borrowed-distractor fault — their
   * distractors are authored, same-concept `confusions` and `applicationWrong`. They
   * leaked anyway, 66.0% and 36.2%, because the rule is `argmax`: 195 of 384 of those
   * distractors DO name the concept and were eliminated regardless, for naming it less
   * densely than the correct answer. Presence is not the bar; matching the density is.
   *
   * Prefixing every option — correct and wrong alike — equalises that density exactly,
   * changes no word of the authored prose, and adds no shape cue, because the form is
   * identical across the set. Nothing here waters down a distractor: an over-claim like
   * "transportation speed alone determines performance" keeps "alone". */
  function labelOptions(values, conceptName) {
    if (!conceptName) return values;
    return values.map(function (value) {
      var body = String(value == null ? "" : value).trim().replace(/\.$/, "");
      if (!body) return value;
      /* Every option takes the same label, including one that already opens on the
         concept's own name. Pronouncing that self-reference as "It" reads better but
         shortens only the correct answer — 11 of 64 summaries open that way — which
         trades the name cue for a length cue and tripped the validator's rank-3
         warning on SPMS. Uniform labelling keeps every length rank exactly as authored. */
      return conceptName + ": " + (/[.!?]$/.test(body) ? body : body + ".");
    });
  }

  function makeQuestion(courseId, concept, perspective, stem, correct, wrong, caselet, shift) {
    var set = rotateOptions(correct, wrong, shift);
    /* Which perspectives get the label, and why it is not all of them.
     *
     * R3 allows either branch — every option names the concept, or none does. The stem
     * decides which is available here:
     *
     *   connect  EXCLUDED. It already names the concept in every option through
     *            CONNECT_WRONG's `{C}` substitution and measures 0.5%; labelling it
     *            again would push it back up toward 25%.
     *   explain  LABELLED, and the redundancy is a knowing trade. Its stem already says
     *            "Which statement best explains <Concept>?", so the label repeats the
     *            subject and the rendered paper shows four options opening on
     *            "LEADS index: " — which reads worse than it measures. Dropping it was
     *            tried on the theory that rewriting the summaries had evened the density
     *            out; it had not. Unlabelled, this family measures **61.9%** with 22 of
     *            47 sets paying 100%, because a summary names its own concept far more
     *            often than its authored confusions do. A short repeated prefix is the
     *            price of closing a 62% exploit, so the label stays.
     *   apply    LABELLED. Its stem is "What is the best interpretation or next step?"
     *            and names nothing, so without the label the only option carrying the
     *            concept's vocabulary is the correct one.
     *
     * Labelling after rotation keeps `set.answer` valid. */
    var labelled = perspective === "apply" || perspective === "explain";
    var options = labelled ? labelOptions(set.options, concept.name) : set.options;
    return {
      id: concept.id + "_" + perspective,
      courseId: courseId,
      conceptId: concept.id,
      module: concept.module,
      source: concept.source,
      node: concept.name,
      pattern: perspective === "explain" ? "Concept check" : perspective === "apply" ? "Application" : "Concept connection",
      perspective: perspective,
      caselet: caselet || "",
      stem: stem,
      options: options,
      answer: set.answer,
      explanation: concept.summary,
      link: concept.bridge
    };
  }

  /* Connect-question distractors.
   *
   * Every "connect" question asks the learner to pick the bridge statement, against
   * the same three misconceptions: a local optimum, a decision closed to evidence,
   * and an idea treated as context-free. Three FIXED strings used to serve all 48 of
   * them, and because a bridge runs 16-22 words while those strings ran 11-14, the
   * correct answer was the longest option in every connect question in the bank.
   * Lengthening them to a single mid-range size only moved the tell: the bridge then
   * landed at rank 3 in most questions and "pick the second-longest" replaced "pick
   * the longest".
   *
   * One fixed triple cannot straddle 48 different correct-answer lengths. So each
   * misconception carries three phrasings of the SAME claim at different lengths, and
   * the generator picks per concept so the bridge lands on a different rank each time.
   * The misconception a learner selects is identical whichever phrasing they saw, and
   * every phrasing maps to that misconception's diagnosis in `t6_diagnoses.js`. */
  /* `{C}` is the concept's own name, substituted per question.
   *
   * These three misconceptions were shared verbatim across all 64 concepts and every
   * one of them opened on a referentless "It". The correct answer is the concept's
   * `bridge`, which necessarily names syllabus content — so the whole family reduced
   * to "pick the only sentence that mentions the subject". A student who had read
   * nothing scored 25 of 25 on them, and a paper carried up to sixteen of them.
   *
   * Naming the concept in each distractor does not make them true; it makes them
   * specific false claims ABOUT this concept, which is what a distractor is for. The
   * three misconceptions themselves are sound and are kept — a local optimum, a
   * decision closed to later evidence, and an idea treated as context-free are real
   * ways to get this wrong. */
  var CONNECT_WRONG = [
    [ // local optimum
      "{C} improves one local measure, so effects elsewhere in the system stop mattering.",
      "{C} improves one local measure, so whatever happens elsewhere in the connected system no longer matters here at all.",
      "{C} improves one local measure, so whatever happens elsewhere in the connected system can be treated as somebody else's problem to solve later on."
    ],
    [ // decision closed to later evidence
      "Once {C} has settled the choice, later evidence should not change the decision.",
      "Once {C} has settled the choice, later evidence should not be allowed to reopen or change the decision.",
      "Once {C} has settled the choice, later evidence should not be allowed to reopen it, because a decision that keeps moving is not really a decision."
    ],
    [ // idea treated as context-free
      "{C} works independently of the people, the constraints, and the decisions around it.",
      "{C} works in exactly the same way independently of the people, the constraints, and the decisions that surround it.",
      "{C} works in exactly the same way regardless of the people involved, the constraints in force, and the decisions being taken around it at the time."
    ]
  ];

  function wordCount(value) {
    return String(value || "").trim().split(/\s+/).filter(Boolean).length;
  }

  /* Choose one phrasing per misconception so that `longerWanted` of the three run
   * longer than the bridge and the rest run shorter — which places the bridge at a
   * chosen rank once the options are sorted by length. The short phrasing is always
   * below a bridge and the long one always above it; the middle phrasing is used
   * whenever it falls on the required side, to keep the option set from reading as
   * two fixed extremes. */
  function connectWrong(bridge, longerWanted, conceptName) {
    var target = wordCount(bridge);
    /* Substitute before measuring: the concept name is part of the option's length,
       so ranking on the template would place the bridge at the wrong rank. */
    var named = CONNECT_WRONG.map(function (variants) {
      return variants.map(function (text) { return text.split("{C}").join(conceptName); });
    });
    return named.map(function (variants, index) {
      var wantLonger = index < longerWanted;
      var middle = wordCount(variants[1]);
      if (wantLonger) return middle > target ? variants[1] : variants[2];
      return middle < target ? variants[1] : variants[0];
    });
  }

  function makeCourse(config) {
    var questions = {};
    var byModule = {};
    config.concepts.forEach(function (concept, index) {
      byModule[concept.module] = byModule[concept.module] || [];
      byModule[concept.module].push(concept);

      var explain = makeQuestion(
        config.id, concept, "explain", "Which statement best explains " + concept.name + "?",
        concept.summary, concept.confusions, "", concept.module + index
      );
      var apply = makeQuestion(
        config.id, concept, "apply", "What is the best interpretation or next step?",
        concept.application, concept.applicationWrong, concept.caselet, concept.module + index + 1
      );
      /* Both the stem and the caselet used to be constants, identical for all 64
         concepts, so a paper could print the same visible prompt sixteen times and
         the item named nothing a candidate could reason about. Both now carry the
         concept, which is what makes the question answerable as written. */
      var connect = makeQuestion(
        config.id, concept, "connect", "Which explanation best connects " + concept.name + " to the wider subject?",
        concept.bridge,
        // Cycle the bridge across all four length ranks rather than pinning it to one.
        connectWrong(concept.bridge, index % 4, concept.name),
        "A student can state what " + concept.name + " is, and now has to say why it changes the next decision.",
        concept.module + index + 2
      );
      explain.repairId = apply.id;
      apply.repairId = connect.id;
      connect.repairId = explain.id;
      questions[explain.id] = explain;
      questions[apply.id] = apply;
      questions[connect.id] = connect;
    });

    config.synthesis.forEach(function (item, index) {
      var concept = config.concepts.filter(function (entry) { return entry.id === item.conceptId; })[0];
      var set = rotateOptions(item.correct, item.wrong, index + 1);
      questions[item.id] = {
        id: item.id,
        courseId: config.id,
        conceptId: item.conceptId,
        module: concept.module,
        source: item.source,
        /* A synthesis question discriminates between frameworks, so it may cite
         * more than the lecture its answer comes from. Declaring every lecture
         * it discriminates between gates it behind all of their lessons, and
         * naming the prerequisite concepts lets a miss route back to the
         * relationship rather than to the answer's concept alone. Defaults
         * preserve the previous single-source behaviour. */
        sourceIds: item.sourceIds || [item.source],
        supportingConceptIds: item.supportingConceptIds || [],
        node: item.node,
        pattern: "Mixed case",
        perspective: "synthesis",
        caselet: item.caselet,
        stem: item.stem,
        options: set.options,
        answer: set.answer,
        explanation: item.explanation,
        link: item.link,
        repairId: concept.id + "_apply"
      };
    });

    var runs = [];
    for (var module = 1; module <= 8; module += 1) {
      var moduleConcepts = byModule[module];
      runs.push({
        id: module,
        module: module,
        title: config.modules[module - 1],
        subtitle: moduleConcepts.map(function (concept) { return concept.name; }).join(" · "),
        minutes: 7,
        questionIds: moduleConcepts.reduce(function (ids, concept) {
          return ids.concat([concept.id + "_explain", concept.id + "_apply"]);
        }, [])
      });
    }
    runs.push({
      id: 9,
      module: 9,
      title: "Connect the whole subject",
      subtitle: "One cause-and-effect question from every module",
      minutes: 11,
      questionIds: config.concepts.filter(function (_, index) { return index % 2 === 0; }).map(function (concept) { return concept.id + "_connect"; })
    });
    runs.push({
      id: 10,
      module: 10,
      title: "Full practice mock",
      subtitle: "Twelve mixed concept and case questions",
      minutes: 18,
      mock: true,
      questionIds: config.concepts.filter(function (_, index) { return index % 2 === 1; }).map(function (concept) { return concept.id + "_connect"; })
        .concat(config.synthesis.map(function (item) { return item.id; }))
    });

    return {
      id: config.id,
      title: config.title,
      shortTitle: config.shortTitle,
      description: config.description,
      modules: config.modules,
      chain: config.modules,
      concepts: config.concepts,
      runs: runs,
      questions: questions
    };
  }

  /* BRGSA concepts carry the same authored fields as the other three subjects.
   *
   * They did not, and that was the whole reason BRGSA written practice marked
   * badly. `conceptData` in t6_challenges.js falls back, when `application` is
   * absent, to the correct option of one of the concept's case questions — a
   * scenario-specific answer choice used as though it were a general decision
   * rule. Both written generators consume that field directly: the short-form
   * exemplar is `summary + application`, and the case rubric states `application`
   * as its entire Decision criterion. So every BRGSA prompt shipped a model
   * answer whose last sentence did not follow from the question, beside a rubric
   * demanding the learner match it. IBM, which has all sixteen authored, marked
   * at 88% on the identical generator.
   *
   * `name` must also describe the anchor lecture, because that lecture is the
   * only evidence the marker is shown. Five did not. Module 4's two were simply
   * swapped and are corrected here by exchanging their sources; the rest are
   * renamed to the topic their lecture actually teaches. */
  function enrichBrgsa(course) {
    var concepts = [
      {id:"brgsa_m1_demand",module:1,source:"BRGSA-M01-L01",name:"Demand validation",match:/lean|validat|landing|smoke|survey/i,
        summary:"Lean validation asks whether real people will take a real action on a real offer, and answers it before the product is built at a fraction of the cost of building it.",
        application:"Turn the demand assumption into a cheap test with a decision threshold declared in advance, before committing build time or budget.",
        bridge:"A test run before the build can still change the decision; the same evidence gathered afterwards can only explain the loss.",
        caselet:"A team leaves customer interviews delighted and books three months of engineering. One member proposes first running a landing page carrying the real price and a deposit button for a week, against the intended audience.",
        caseEvidence:"The team is about to commit three months of engineering on interview enthusiasm alone, so running the priced landing page first tests the same assumption while the decision can still change."},
      {id:"brgsa_m1_evidence",module:1,source:"BRGSA-M01-L04",name:"Pre-sales commitment and evidence strength",match:/commit|pre.order|evidence|signal/i,
        summary:"Demand signals sit on a commitment spectrum: social engagement is the easiest to produce and the least meaningful, while a payment or signed commitment is a different category of evidence altogether.",
        application:"Weight every demand signal by what it cost the prospect to give, and require a real commitment before treating demand as proven.",
        bridge:"Free actions are easy to take without conviction, so only a signal the prospect paid something for predicts that they will pay again.",
        caselet:"Two hundred people say they like the idea, thirty join a wait-list, and four accept a refundable deposit under stated terms. The founder wants to report the survey as the strongest demand signal.",
        caseEvidence:"Two hundred people expressed approval and four paid a refundable deposit, so those four are the only signal that cost the prospect anything and therefore the only one that predicts payment."},
      {id:"brgsa_m2_design",module:2,source:"BRGSA-M02-L01",name:"Null hypothesis and test design",match:/null|sample|experiment|proxy/i,
        summary:"An experiment starts from the null position that nothing changed, and the variant earns the decision only when evidence collected to a pre-set sample is strong enough to reject it.",
        application:"State the null, the sample size and the decision threshold before the test runs, and hold them when the interim numbers look encouraging.",
        bridge:"Thresholds fixed before the data arrives are what stop a favourable early reading from rewriting the conclusion.",
        caselet:"A team compares two onboarding flows, opens the dashboard on day three, sees the preferred variant ahead, and wants to declare a winner before the planned sample is reached.",
        caseEvidence:"The team is reading a day-three result against a sample it has not yet reached, so the encouraging interim number is exactly what the pre-set threshold exists to discount."},
      {id:"brgsa_m2_error",module:2,source:"BRGSA-M02-L03",name:"Decision errors",match:/type|error|false|cost/i,
        summary:"A Type I error scales something that does not work; a Type II error abandons something that does. Every test outcome lands in one of the four cells of that matrix.",
        application:"Decide which of the two errors is more costly for this particular decision, then set the sample size and threshold to protect against that one.",
        bridge:"A false positive shows up later as wasted spend; a false negative stays invisible, because the gain that was abandoned never appears in any report.",
        caselet:"An underpowered test on a genuinely better pricing page reports no difference, the team keeps the old page, and the forgone gain would have compounded across every future cohort.",
        caseEvidence:"The test was underpowered against a change that was genuinely better, so this is a false negative whose cost is the compounding gain now abandoned rather than any visible loss."},
      {id:"brgsa_m3_cohort",module:3,source:"BRGSA-M03-L01",name:"Cohorts and retention",match:/cohort|retention|shape/i,
        summary:"A cohort groups users by when they entered so retention can be compared at equal age, which aggregate totals cannot do because they mix new arrivals with survivors.",
        application:"Read retention by signup cohort and time since entry before concluding from a rising total that growth is working.",
        bridge:"Acquisition can refill a leaking bucket indefinitely, so only the cohort curve shows whether the bucket itself improved.",
        caselet:"Total active users climb every month while each newer signup cohort holds fewer users at week four than the cohort before it, and the team plans to increase spend.",
        caseEvidence:"Each newer cohort holds fewer users at week four while the total still climbs, so acquisition is sustaining the headline number while the product's retention deteriorates underneath it."},
      {id:"brgsa_m3_economics",module:3,source:"BRGSA-M03-L04",name:"CAC and LTV",match:/cac|ltv|economic|scale/i,
        summary:"CAC carries no decision meaning without an estimate of the value it buys, so LTV is estimated early from observed lifespan, margin and revenue rather than waited for.",
        application:"Estimate LTV from the cohort behaviour already visible, compare it with CAC segment by segment, and let that ratio decide which segment to acquire more of.",
        bridge:"An early LTV rests on assumptions that must be revisited as cohorts mature, because the ratio they produce drives every scaling decision after it.",
        caselet:"One segment returns close to five times its acquisition cost and another barely one, yet the team spends equally on both because the blended figure looks acceptable.",
        caseEvidence:"One segment returns close to five times its acquisition cost and another barely one, so the blended figure hides which of them is actually worth funding."},
      /* Module 4's two concepts had their anchors exchanged: "Growth constraint"
       * pointed at the stage lecture and "First customers" at the constraint
       * lecture. Both lectures are already in the frozen evidence pack, so the
       * sources are swapped back rather than re-indexed. That alone restores
       * "Growth constraint". The second concept still needed renaming: the
       * lecture it now anchors teaches early-stage versus scale-stage growth,
       * and no lecture in the pack covers first customers on its own. */
      {id:"brgsa_m4_constraint",module:4,source:"BRGSA-M04-L04",name:"Growth constraint",match:/constraint|bottleneck|narrowest|funnel/i,
        summary:"At any moment one stage of the funnel limits the whole system, and improving any other stage moves the end-to-end outcome very little.",
        application:"Locate the single narrowest stage with funnel and cohort math, and work only on it until it is no longer the constraint.",
        bridge:"A constraint is worth attacking only when it is within your control and removing it would produce a large end-to-end lift.",
        caselet:"Traffic doubles after a campaign, activation stays flat, most new users abandon the same setup step, and the team asks for more acquisition budget.",
        caseEvidence:"Traffic doubled while activation stayed flat and users still abandon the same setup step, so activation is the binding constraint and further acquisition spend cannot move the outcome."},
      {id:"brgsa_m4_customers",module:4,source:"BRGSA-M04-L02",name:"Early-stage and scale-stage growth",match:/founder|early|stage|rung|ladder|acqui/i,
        summary:"Early-stage growth is a search for repeatability run close to the founder; scale-stage growth optimises a motion already known to work, and the same move can be right at one stage and wrong at the other.",
        application:"Place the company on the ladder of proof first, and run the playbook belonging to that rung rather than the one its funding suggests.",
        bridge:"Early learning has to stay close to whoever can change the product, because a scale-stage system assumes the motion no longer needs changing.",
        caselet:"A company raises a round, hires a performance marketer and wires attribution across five tools, while nobody has yet asked the last ten customers why they bought.",
        caseEvidence:"Nobody has yet asked the last ten customers why they bought, so the company is buying scale-stage machinery while still on a rung whose open question is whether the motion works at all."},
      {id:"brgsa_m5_channel",module:5,source:"BRGSA-M05-L01",name:"Channel fit",match:/channel|outbound|organic|loop/i,
        summary:"Every channel has fixed properties — targeting, control, input cost, output quality, time to result and economics — and it fits only when those match the product's buyer and unit economics.",
        application:"Score candidate channels against the product's economics and timing constraints before spending, and reject one that fails any single dimension.",
        bridge:"A channel can reach exactly the right buyer and still fail on cost or time to result, so fit has to hold on every dimension at once.",
        caselet:"A channel reaches the intended buyer precisely but takes fourteen months to produce revenue, and the company has three months of runway.",
        caseEvidence:"The channel needs fourteen months to return revenue against three months of runway, so it fails on time to result however precisely it reaches the buyer."},
      {id:"brgsa_m5_activation",module:5,source:"BRGSA-M05-L05",name:"Activation and onboarding friction",match:/aha|activat|friction/i,
        summary:"Activation is the first observable moment a user experiences the promised value, and every step standing between signup and that moment sheds a share of the users still remaining.",
        application:"Audit the whole path to first value, classify the friction at each step, and remove or defer anything that does not help the user reach it.",
        bridge:"Each drop applies to whoever is left, so several individually reasonable steps can destroy an activation rate that no single step explains.",
        caselet:"Registrations rise sharply after a campaign, but most users leave somewhere inside a twelve-step onboarding flow before the product has done anything for them.",
        caseEvidence:"Most users leave inside a twelve-step flow before the product has done anything for them, so the loss is friction ahead of first value rather than a shortage of registrations."},
      {id:"brgsa_m6_habit",module:6,source:"BRGSA-M06-L01",name:"Habit and lifecycle",match:/habit|lifecycle|retention/i,
        summary:"Durable retention comes from a repeatable trigger, action, variable reward and investment loop in which the user returns unprompted, not from more frequent prompting.",
        application:"When retention falls, name which phase of the loop broke and repair that phase, instead of adding email or discounts.",
        bridge:"External triggers pull users back only while you keep paying for them; an internal trigger is what lets the loop sustain itself.",
        caselet:"A team copies a daily streak mechanic into a product customers genuinely need only during an occasional high-stakes event, and engagement rises while retention does not.",
        caseEvidence:"The product is genuinely needed only during an occasional high-stakes event, so a daily streak supplies a trigger the user's own life does not, and engagement rises without retention following."},
      {id:"brgsa_m6_churn",module:6,source:"BRGSA-M06-L05",name:"Referral and network effects",match:/churn|referral|network/i,
        summary:"A referral loop brings one more user; a network effect makes the product more valuable to the users already there as more relevant users join. Brand recognition, scale economies and embedded incentives are routinely mistaken for the second.",
        application:"Apply the joining test — does one more user make the product more valuable to existing users — and run the referral playbook when the answer is no.",
        bridge:"Claiming a network effect that does not exist leads a team to defend a moat it does not have.",
        caselet:"A reward campaign produces a signup spike, the referred users churn before reaching value, and existing users report no change in what the product is worth to them.",
        caseEvidence:"Existing users report no change in what the product is worth to them as others join, so this is a referral incentive rather than a network effect."},
      {id:"brgsa_m7_pricing",module:7,source:"BRGSA-M07-L01",name:"Pricing structure and NRR",match:/pricing|nrr|revenue/i,
        summary:"Pricing is a structure rather than a number: tiers, units, limits and packaging decide how customers enter, upgrade and expand, and NRR measures whether the existing base grows without counting new customers.",
        application:"Design the pricing structure around the expansion behaviour the business needs, and read NRR on the existing cohort before crediting growth to it.",
        bridge:"Two companies charging the same average revenue per user grow at different rates when one structure contains an upgrade path and the other does not.",
        caselet:"A subscription loses some accounts while retained customers expand enough that recurring revenue still rises; the team reports only logo churn and plans more acquisition.",
        caseEvidence:"Retained customers expanded enough to grow recurring revenue while logo churn was the only figure reported, so NRR on the existing cohort is the number that shows whether the base is healthy."},
      {id:"brgsa_m7_pipeline",module:7,source:"BRGSA-M07-L04",name:"Sales integration and payback",match:/pipeline|handoff|payback|motion|sla/i,
        summary:"Revenue crosses several team handoffs, and each needs an entry criterion, an owner, the context that must travel with it and a response-time SLA; payback measures how long acquisition cash stays tied up before gross profit returns it.",
        application:"Define each handoff's criteria, context, owner and response time, and choose channels by how fast they repay acquisition cost rather than by CAC alone.",
        bridge:"Every team can hit its own target while the customer stalls between them, because nobody owns the transition itself.",
        caselet:"Marketing reports a hundred qualified leads and sales counts seventy-five, the two definitions were never agreed, leads sit untouched for days, and the channel funding all of it takes eighteen months to repay.",
        caseEvidence:"Marketing counted a hundred qualified leads and sales counted seventy-five against a definition never agreed between them, so the handoff criteria and response time are the leak rather than lead volume."},
      {id:"brgsa_m8_priority",module:8,source:"BRGSA-M08-L01",name:"Prioritisation",match:/ice|backlog|priorit|allocation/i,
        summary:"ICE scores each idea on impact against the current constraint, confidence backed by evidence that can be named, and ease including the time to a credible signal, turning a list of ideas into an ordered backlog.",
        application:"Score every candidate experiment against the current primary constraint, and cap confidence at five whenever the supporting evidence cannot be named in one sentence.",
        bridge:"A high score on a metric that is not the constraint earns no capacity, however much that metric improves.",
        caselet:"A high-visibility feature scores well on team enthusiasm, has no evidence behind its confidence score, needs a quarter of engineering, and does not touch the activation step the funnel math identified.",
        caseEvidence:"The feature does not touch the activation step the funnel math identified, so its impact score cannot be high however much enthusiasm it attracts."},
      {id:"brgsa_m8_decision",module:8,source:"BRGSA-M08-L03",name:"Decision rules",match:/decision|rule|vanity|metric/i,
        summary:"A metric earns a place on the dashboard only when it carries an owner, a threshold, and an action already agreed for the moment it crosses that threshold.",
        application:"Pre-register the decision each metric will trigger before the result arrives, so a movement in the number changes an action rather than a narrative.",
        bridge:"A metric with no owner and no threshold records what happened; it cannot cause anything to be done differently.",
        caselet:"A dashboard celebrates visits and downloads every week, but no number has an owner, a threshold, or a stated action for when it moves.",
        caseEvidence:"No number on the dashboard carries an owner or a threshold, so the weekly review can celebrate movement without any action following from it."}
    ];
    var modules = ["Validate demand", "Design fair tests", "Read the evidence", "Find the growth constraint", "Acquire and activate", "Retain customers", "Price and sell", "Operate the system"];
    Object.keys(course.questions).forEach(function (id) {
      var question = course.questions[id];
      var sourceModule = Number((String(question.source).match(/-M(\d\d)-/) || [0, question.module])[1]);
      var module = sourceModule >= 1 && sourceModule <= 8 ? sourceModule : Math.min(8, Math.max(1, question.module || 1));
      var candidates = concepts.filter(function (concept) { return concept.module === module; });
      var text = [id, question.node, question.stem].join(" ");
      var concept = candidates.filter(function (entry) { return entry.match.test(text); })[0] || candidates[id.length % candidates.length];
      question.courseId = "BRGSA";
      question.conceptId = concept.id;
      question.perspective = /case|application|decision|synthesis/i.test(question.pattern || "") ? "apply" : "explain";
    });
    concepts.forEach(function (concept) { delete concept.match; });
    course.description = "Business research, growth decisions, customer behaviour, and analytics.";
    course.modules = modules;
    course.chain = modules;
    course.concepts = concepts;
    course.runs[8].title = "Connect the whole subject";
    course.runs[8].subtitle = "One cause-and-effect question from every module";
    course.runs[9].title = "Full practice mock";
    course.runs[9].subtitle = "Twelve mixed concept and case questions";
    return course;
  }

  if (window.T6_COURSE) catalogue.BRGSA = enrichBrgsa(window.T6_COURSE);

  catalogue.IBM = makeCourse({
    id: "IBM",
    title: "Inclusive Business Models",
    shortTitle: "IBM",
    description: "How financially sustainable organisations serve underserved people and measure real impact.",
    modules: ["Inclusive business basics","Affordable health and education","Responsible finance and agriculture","Rural employment models","Shared value and energy access","Informal work and waste","Farmer organisations and social business","Impact investment and measurement"],
    concepts: [
      {id:"ibm_inclusive",module:1,source:"IBM-M01-L03",name:"Inclusive business",summary:"An inclusive business must always do both: meet a specific need of underserved people, and remain financially sustainable.",confusions:["Any profitable firm is inclusive if it sells a useful product to anyone who needs it.","An inclusive business must maximise shareholder profit first and treat social outcomes as whatever remains once returns are secured.","Only grant-funded charities can be inclusive, because charging a customer anything ends the social purpose."],caselet:"Sanjeevani Clinics runs eleven centres in low-income urban districts. A consultation costs ₹120 against ₹600 at the nearest private hospital, and 78% of its patients earn under ₹15,000 a month. Fees cover operating costs and fund two new centres a year, while a philanthropic grant covered only the original fit-out. A consultant now proposes adding a cosmetic dermatology line at ₹4,000 a visit, arguing the margin would let the group expand faster. The existing centres already run at 94% capacity with a three-day wait.",caseEvidence:"Fees of ₹120 already cover operating costs and fund two new centres a year, so the model sustains its own expansion without turning 94%-occupied capacity away from the patients it exists to serve.",application:"Treat it as inclusive because serving an underserved need is the primary purpose and the model always sustains itself.",applicationWrong:["Treat it as ordinary CSR, because social activity always sits outside the business model and is funded from profit.","Reject it as inclusive, because charging any fee to an underserved customer cancels the social purpose the model was built to serve.","Call it inclusive only if shareholder return is its sole objective, since financial discipline is what separates a real business from charity."],bridge:"Financial sustainability keeps the social solution available; the underserved need determines what the model is built to do."},
      {id:"ibm_bop",module:1,source:"IBM-M01-L07",name:"Bottom-of-the-pyramid design",summary:"Serving bottom-of-the-pyramid markets always requires prices and delivery redesigned for structural constraints, never smaller copies of rich-market offers.",confusions:["The model depends only on very high margins per customer, since poor households buy rarely and must be charged more.","A product becomes inclusive as soon as it is sold in a developing economy, regardless of its price or design.","Existing premium products can be moved unchanged into poorer markets, because a good product sells wherever there is genuine unmet need."],caselet:"A packaged foods company sells a 2 kg fortified flour pack at ₹340, payable in a single transaction, through 400 urban supermarkets. It targets rural districts holding 90 million people and has reached 0.3% of them in two years. Field visits find median household cash arrives weekly rather than monthly, the nearest stocking retailer is 14 km away, and 2 kg exceeds what most families can store safely through the humid season. The country manager proposes doubling the advertising budget, citing the size of the untapped population.",caseEvidence:"Households receive cash weekly while the pack demands ₹340 at once from a retailer 14 km away, so the barrier is the offer's price point, unit size and access rather than any shortage of potential buyers.",application:"Redesign affordability, access and service around the constraints, because population size is never demand by itself.",applicationWrong:["Keep the offer unchanged, because a large population guarantees enough buyers will convert.","Raise the pack size so each individual sale produces a larger absolute margin for the firm.","Target only wealthy urban buyers while still describing the offer as a bottom-of-the-pyramid model in reporting."],bridge:"A large underserved population becomes a market only when the offer removes the affordability and access barriers that suppress use."},
      {id:"ibm_vaatsalya",module:2,source:"IBM-M02-L04",name:"No-frills healthcare access",summary:"Vaatsalya placed low-cost hospitals in semi-urban areas to cut patients' travel burden, trimming only costs that left essential quality intact.",confusions:["Its main advantage was adding premium tertiary care in major cities where specialist demand is already concentrated.","It solved access by arranging transport so every rural patient could reach an existing tertiary hospital in the nearest city.","The model depended on avoiding quality controls so that costs could be cut far enough to reach much poorer patients."],caselet:"A hospital group runs six 200-bed tertiary facilities in three large cities, whose cardiac and oncology units sit at 61% occupancy. Its own records show 44% of admissions travel more than 90 km, most for deliveries, dialysis and routine surgery needing no tertiary equipment. A normal delivery costs the patient about ₹38,000. A proposal on the table is a network of 40-bed centres in semi-urban towns handling primary and secondary care only, at an estimated ₹11,000 per delivery and staffed by locally recruited clinicians.",caseEvidence:"Forty-four per cent of admissions travel over 90 km for care that needs no tertiary equipment, so placing 40-bed secondary centres near those patients removes the access burden the ₹38,000 city pathway imposes.",application:"Locate a quality-controlled facility nearer the population, cutting only costs that leave essential care intact.",applicationWrong:["Open another premium tertiary hospital in the city and let patients travel to it.","Remove trained staff so the price falls, on the view that cost is the only barrier patients actually face.","Offer only a transport subsidy without addressing whether local care capacity exists at all."],bridge:"Where care is located changes who can use it; cost discipline matters only if essential quality and access remain intact."},
      {id:"ibm_aravind",module:2,source:"IBM-M02-L08",name:"Process specialisation in healthcare",summary:"Aravind standardised pre- and post-operative work for paramedics so surgeons focused on surgery, never at the cost of clinical quality.",confusions:["Every activity stayed with the surgeon so that consistency and utilisation of the specialist were both preserved.","Capacity increased mainly by reducing the number of patients treated so each case could be given longer.","The model removed clinical judgement from the surgical step itself and turned the operation into a routine task anyone could repeat."],caselet:"An eye hospital has four ophthalmologists and a nine-week cataract waiting list. A time study finds each surgeon spends 71% of the working day on counselling, vision measurement, dilation checks and post-operative dressing, and 29% operating. Complication rates sit at the national benchmark and the trustees have said that must not move. The hospital already employs 22 trained paramedical staff, mostly assigned to reception. A consultant proposes recruiting two more surgeons, at a cost current surpluses cannot fund.",caseEvidence:"Surgeons spend 71% of the day on counselling, measurement and dressing that the 22 trained paramedical staff already on the payroll could take over, so redistributing that work raises surgical throughput without recruiting the scarce specialist.",application:"Separate standardisable tasks for trained support staff so the specialist concentrates on the constrained surgical step.",applicationWrong:["Ask the surgeon to perform every task personally so the whole process stays consistent.","Reduce theatre use so that staff have more idle time between cases and mistakes fall.","Let untrained staff perform the surgery as well as the preparation, since the whole cycle is standardised."],bridge:"Specialisation raises throughput when routine work is separated from the scarce expert task without lowering clinical quality."},
      {id:"ibm_grameen",module:3,source:"IBM-M03-L03",name:"Group-based microfinance",summary:"The classic Grameen model lent without collateral using group knowledge and peer accountability, which holds only while repayment capacity stays real.",confusions:["It replaced borrower assessment altogether with unlimited individual lending to anyone who asked for it in the village.","It depended on a formal credit bureau to select every village borrower before any loan was made.","All group members received large loans at the same time without conditions, so nobody had to wait for anyone else's repayment."],caselet:"A lender wants to reach 30 villages where 82% of households hold no bank-acceptable collateral and no formal credit record, and its two field officers cannot assess 4,000 households individually. A pilot in four villages lent to self-formed groups of five women, releasing funds to two members first and to the rest only after the first repayments arrived, with weekly meetings held in the village. Repayment reached 97% over eighteen months. Head office now proposes dropping the meetings and the staged release to cut cost per loan, keeping the group label.",caseEvidence:"The 97% repayment came from a design in which only two members held funds until the first repayments arrived and the group met weekly, so removing the staging and the meetings removes the mechanism that produced the result rather than trimming its overhead.",application:"Use formed groups, staged lending and local monitoring, which works only while repayment capacity stays real.",applicationWrong:["Issue repeated loans without checking repayment capacity, because a good repayment record settles the question.","Ignore what the group knows and lend against sales-agent targets instead, since loan volume proves the model is working.","Require urban property collateral from every applicant, since no loan is safe without a registered asset."],bridge:"Local information can reduce screening risk, but the structure works only when repayment capacity and group discipline remain real."},
      {id:"ibm_responsible_lending",module:3,source:"IBM-M03-L05",name:"Responsible lending",summary:"Responsible lending checks total debt and repayment capacity, and never lets loan volume outrun the screening that made inclusion viable.",confusions:["More simultaneous loans always prove stronger financial inclusion, because access to more credit is what inclusion is measuring.","A prior lender's approval removes the need for fresh due diligence, since somebody has already checked this household's finances carefully.","Sales incentives are a reliable substitute for capacity checks, because officers will not lend where repayment looks doubtful to them."],caselet:"A microfinance institution has grown disbursements 140% in two years. Field agents earn 60% of their variable pay per additional loan disbursed and nothing tied to repayment. A sample of 500 borrowers finds the median household now services four concurrent microloans, 38% used their most recent loan to repay an existing one, and total monthly debt service reaches 71% of reported household income. Portfolio-at-risk still reads 1.2%, because refinancing keeps accounts current. The growth committee wants two new districts next quarter.",caseEvidence:"Thirty-eight per cent of borrowers used the newest loan to repay an older one while debt service reached 71% of income, so the 1.2% portfolio-at-risk reflects refinancing rather than repayment capacity and cannot justify entering new districts.",application:"Pause lending, assess total obligations and cash flow, and never let volume incentives outrun borrower capacity.",applicationWrong:["Approve quickly, because the earlier lenders must already have checked this household's total obligations and cash flow.","Add another loan so the household can keep up its existing repayments for a few more months.","Judge success only by the number of accounts opened, since reach is the outcome this programme was set up to deliver."],bridge:"Access becomes harmful when debt service outruns income; scale must preserve the screening practices that made inclusion viable."},
      {id:"ibm_rural_bpo",module:4,source:"IBM-M04-L04",name:"Rural BPO model",summary:"RuralShores adapted BPO work, training and location to rural conditions while never relaxing the service quality clients buy on.",confusions:["It copied an urban international-call-centre model without changes and simply moved it to a village.","Its clients accepted poor service because the mission was social and the contract supported rural employment in the region.","It created impact mainly by selling consumer goods to rural workers rather than by employing them in skilled work."],caselet:"A BPO is considering a delivery centre in a district town where about 1,200 graduates enter the market each year and few migrate for work. Wage expectations run 40% below the metro rate, and attrition at comparable rural centres is 8% against 45% in cities. The available contracts are document processing and regional-language customer support, with a client quality bar of a 2% error ceiling audited monthly. Local candidates have strong regional-language ability and little exposure to accented international voice work, and the town loses power for about 90 minutes a day.",caseEvidence:"Local graduates bring strong regional-language ability and 8% attrition but little accented-voice exposure, so scoping the centre to document processing and regional-language support keeps the audited 2% error ceiling credible while the employment benefit stays real.",application:"Choose suitable domestic processes, train local staff, and adapt operations without relaxing client service standards.",applicationWrong:["Compete only for English-heavy international voice work, since that is where the margins sit.","Ask clients to accept lower service quality as their social contribution towards creating rural employment.","Move the centre to a metro while retaining the rural label in all client reporting and marketing."],bridge:"The model creates employment because business processes are redesigned around local capability while market-facing quality remains credible."},
      {id:"ibm_replication",module:4,source:"IBM-M04-L05",name:"Replicating rural services",summary:"Rural service models scale through trusted local partners rather than capital-heavy control, under standards every partner must meet.",confusions:["Replication means every centre must be owned and run directly by the parent organisation to hold quality.","Local partners matter only after national scale is reached, since early growth depends entirely on central capital and control.","Low price alone is enough to win outsourced critical work, because clients ultimately buy on cost rather than on demonstrated capability."],caselet:"A rural services company runs eight centres it owns and staffs directly, and holds requests from 60 towns. It has ₹4 crore of capital against ₹90 lakh needed per owned centre, and nobody who knows hiring conditions in those towns. Two pilots run by local entrepreneurs who funded their own fit-out reached break-even in seven months against eleven for owned centres. One of those pilots missed the group's training standard, and a client audit flagged inconsistent output quality across the network.",caseEvidence:"Partner-run pilots reached break-even in seven months on the partners' own capital while one breached the training standard and triggered a client audit, so growth should run through local partners bound to common standards rather than owned centres the ₹4 crore cannot fund.",application:"Use a controlled partner model with local credibility and standards every partner must meet.",applicationWrong:["Own every centre directly regardless of the capital required or local acceptance.","Let each partner invent its own service standards independently of any shared certification requirement.","Rely only on price discounts to win contracts and omit quality certification from the model entirely."],bridge:"Local partnership lowers entry friction and capital needs; common standards stop distributed growth from weakening trust."},
      {id:"ibm_shared_value",module:5,source:"IBM-M05-L07",name:"Shared value",summary:"Shared value solves a social problem through the business model, and holds only when doing so also strengthens the economics that fund it.",confusions:["It is redistributing profit at the end of the year while harmful operations continue unchanged elsewhere in the business.","Any profitable activity creates shared value automatically, because a growing firm eventually lifts everyone who is connected to it.","It requires the firm to stop earning a return, since a genuine social contribution cannot also be profitable for shareholders at the same time."],caselet:"A dairy processor buys from 12,000 smallholders. Rejections for bacterial count run at 19%, forcing spot purchases at a 23% premium whenever supply falls short. Farmers average 4.1 litres per animal per day against a 7-litre regional benchmark, and most sell through intermediaries who deduct 15%. A proposal would fund village chilling units, veterinary services and direct payment at ₹6 crore over three years, projected to lift yield to 6 litres, cut rejections to 6% and raise farmer realisation by 22%. The CFO asks why a processor should pay for farm productivity.",caseEvidence:"Rejections at 19% force spot purchases at a 23% premium, so funding chilling and veterinary services attacks the processor's own supply cost at the same time as it raises farmer income.",application:"Evaluate whether the operating model creates additional value for both the firm and farmers rather than merely donating after profit is made.",applicationWrong:["Count it as shared value only if the firm loses money on the arrangement, since financial sacrifice is what proves sincerity.","Ignore farmer outcomes altogether, because the firm's own profitability already proves the shared-value claim.","Classify any statutory donation as an integrated supply-chain model, since the money reaches the same community either way."],bridge:"The business becomes more durable when solving a stakeholder constraint also strengthens the economics that fund the solution."},
      {id:"ibm_selco",module:5,source:"IBM-M05-L10",name:"SELCO affordability system",summary:"SELCO linked solar products, independent finance and reliable service into one system, where removing any single link makes the offer unusable.",confusions:["Affordability meant giving every customer the same free product regardless of what their own work actually required.","SELCO maximised sales by approving its own customer loans as well as supplying, installing, and servicing the equipment itself.","After-sale service was optional because solar equipment carries no downtime risk once it has been correctly installed the first time."],caselet:"A street vendor trades until 9 pm and spends ₹15 a day on kerosene, about ₹450 a month, for light poor enough that customers leave early. A solar unit costs ₹9,000 outright, which she cannot pay, but a rural bank will finance it at ₹10 a day over three years once repayment capacity is shown. Brighter light is expected to raise daily takings by about ₹90. Two earlier solar programmes in the district failed when units broke and no technician was available within 40 km, and villagers now say they will not buy without a repair promise.",caseEvidence:"She already spends ₹15 a day on kerosene against ₹10 a day of financing that also raises takings by ₹90, so the offer only works if the finance and a local repair service both hold — the two links the failed programmes lacked.",application:"Bundle the light with finance and dependable service, since removing any one of those links makes it unusable.",applicationWrong:["Sell the largest system available and let SELCO approve the customer's debt itself rather than a bank.","Ignore servicing once the purchase is complete, because the sale has already been recorded and paid for.","Require the full price upfront despite the customer's daily cash flow, since arranging third-party finance only complicates and delays the sale."],bridge:"Product, finance, livelihood benefit, and uptime form one affordability system; removing any link can make the offer unusable."},
      {id:"ibm_labournet",module:6,source:"IBM-M06-L02",name:"LabourNet platform",summary:"LabourNet improved worker mobility through identity, skills, market links and institutional access, which opens only when all four arrive together.",confusions:["It addressed informal work only by issuing one-time cash grants to workers who registered on the platform.","Its model assumed migrant workers already had trusted identities and bank access before they arrived in the city.","The platform worked by preventing workers from changing employers, so that placements would remain stable for the firms hiring them over time."],caselet:"Migrant construction workers in a metro lose an average of nine days a month searching for work and are paid 18% below rate when hired through informal brokers. Almost none hold a document proving prior work, and 91% have no bank-recognised identity, so contractors treat them as unverifiable risk and insurers decline cover. A platform proposes registering workers with verified identity, independently assessed skill grades and a logged work history, then matching them to contractors. Contractors say they will pay a premium only where the skill grade is independently assessed rather than self-declared.",caseEvidence:"Contractors will pay above the informal rate only for independently assessed skill grades, and 91% of these workers have no recognised identity at all, so verified identity and assessment are what convert existing skill into income.",application:"Build worker records, skills and institutional links together, because access opens only when all of them arrive at once.",applicationWrong:["Offer a job listing service without solving the identity or trust problem underneath it.","Exclude the most mobile workers, because keeping records on them is difficult.","Measure impact only by the number of registrations recorded, not by what changed for the worker."],bridge:"Identity makes skills and work history legible; that trust opens market and institutional access that income mobility requires."},
      {id:"ibm_waste",module:6,source:"IBM-M06-L05",name:"Inclusive waste enterprise",summary:"An inclusive waste enterprise creates shared value only when recovery, product demand and worker livelihoods all hold together.",confusions:["Selling recycled products is sufficient even if the waste workers themselves end up worse off than they were before collection started.","Environmental benefit cancels the need for financial viability, because the ecological case alone justifies keeping the enterprise running.","Workers can only ever participate as low-paid employees, never as owners or decision-makers in the enterprise they supply."],caselet:"Temples in one city send about 8 tonnes of flower waste a week to landfill, where it decomposes into a local waterway. A venture collects it free, converts it into incense and natural dyes, and employs 60 women from nearby low-income settlements at ₹11,000 a month against the ₹6,500 they earned in informal work. Retail buyers pay a premium for the provenance and current output sells out. Scaling to 20 tonnes needs a second site and either mechanised sorting, which would halve the workforce, or 60 more women hired and trained.",caseEvidence:"The premium retail buyers pay rests on provenance built by 60 women now earning ₹11,000 against ₹6,500, so mechanising the sorting step would cut the workforce the product's own market position depends on.",application:"Track pollution reduction, product economics and worker livelihoods, which count as shared value only when all three hold.",applicationWrong:["Claim inclusion from the recycling volume alone, without reporting any worker outcomes.","Ignore product demand entirely, because environmental intent guarantees that the enterprise will survive on its own.","Replace livelihood measures with the total tonnage of waste collected each month."],bridge:"Waste becomes shared value only when material recovery, customer demand, and worker welfare reinforce one another."},
      {id:"ibm_fpo",module:7,source:"IBM-M07-L04",name:"Farmer Producer Organisation",summary:"An FPO pools farmer ownership and volume, but that scale never becomes income without market access and managerial capability.",confusions:["An FPO is owned by an outside trader who buys the crop from the member farmers directly.","Its main purpose is to keep every farmer selling separately so each can negotiate their own price with the buyer.","Market linkage becomes unnecessary once farmers contribute equity, since ownership on its own secures a better price at the market."],caselet:"Nine hundred farmers in one block grow a distinctive aromatic rice. Each markets 2 to 4 tonnes through village traders at ₹22 a kg, while the same rice retails in city stores at ₹95. No individual farmer can meet a retailer's 200-tonne minimum consignment or fund the certification a premium buyer requires. A producer company has been registered with the farmers as shareholders and grant funding covers three years of working capital, but it has nobody with buyer relationships, packaging experience, or the means to hold quality across 900 growers. A neighbouring FPO collapsed after two seasons for exactly that reason.",caseEvidence:"Aggregating 900 growers would clear the 200-tonne consignment, but the neighbouring FPO collapsed for want of buyer relationships and quality control, so professional management is what turns the collective's scale into farmer income.",application:"Aggregate through a farmer-owned organisation and build market links, because scale never becomes income without them.",applicationWrong:["Keep volumes fragmented and negotiate farm by farm with each buyer as the season goes on.","Transfer ownership entirely to a distant buyer who already has market access.","Focus on registration counts and member numbers without building any sales or value-adding capability."],bridge:"Collective ownership turns fragmented production into scale, but market access and managerial capability convert that scale into income."},
      {id:"ibm_social_business",module:7,source:"IBM-M07-L05",name:"Social business",summary:"A social business puts social impact first inside a no-loss operating model, and never depends only on periodic donations.",confusions:["It maximises distributable profit for its owners and treats social impact as an optional extra alongside the main commercial objective.","It is identical to employee volunteering, since both put company time and resources behind a social cause outside the business.","It must depend permanently on grants and cannot earn revenue, because charging its customers anything would compromise the social mission it was set up to serve."],caselet:"A food company creates a fortified snack for children in low-income districts, priced at ₹5 so the target households can actually buy it. The line covers its own costs and repays the investors' original capital, after which surplus is reinvested in distribution rather than paid out. Nutrition surveys show a measurable fall in deficiency among regular consumers. The group board asks why the line should not instead be run as CSR funded from group profit, or priced at ₹12 where the same product would earn a normal margin from wealthier urban buyers.",caseEvidence:"The line covers its costs and repays original capital at the ₹5 price the target households can pay, so it continues year after year without depending on the annual budget decision CSR funding would require.",application:"Judge whether the social goal drives the model and discipline keeps it running, never letting profit become the purpose.",applicationWrong:["Call it ordinary CSR because it sells a product, and treat the stated social goal as a marketing position.","Require maximum dividends to shareholders before considering impact, since any business must first satisfy the owners who funded it.","Treat continuing losses as proof that the model is socially serious, since any profit would suggest the social mission had slipped."],bridge:"A social purpose becomes repeatable when it sits inside a no-loss operating model instead of depending only on periodic donations."},
      {id:"ibm_impact_investing",module:8,source:"IBM-M08-L01",name:"Impact investing",summary:"Impact investing needs all three of intent, measurement and financial return present together; it is never a grant.",confusions:["Any investment in a profitable company is an impact investment, because profitable firms create jobs and pay taxes.","Impact intent matters, but measurement and reporting do not, since the aim is what defines the investment.","Impact investing excludes all financial return, since accepting a return would make it ordinary commercial capital rather than philanthropy."],caselet:"A fund raises ₹500 crore for affordable housing. It sets a target that 70% of units go to households below a stated income line, requires quarterly reporting on who actually occupies them, and expects a 9% return so the capital can be recycled into further projects. One developer in the pipeline offers 16% but will commit to only 25% of units below the income line, and proposes reporting sales value rather than buyer income. The investment committee is split, noting the fund's headline return currently sits below its target.",caseEvidence:"The developer offers 16% but commits to only 25% of units below the income line and would report sales value instead of buyer income, so accepting it abandons both the intent and the measurement that make this capital an impact investment.",application:"Classify it as impact investing because intent, measurement and return are all designed together.",applicationWrong:["Classify every housing share purchase as impact investing, whatever the intent behind it.","Treat it as philanthropy because it has a social target, and expect no financial return at all.","Ignore outcome reporting once the capital has been deployed and the investment is live."],bridge:"Intent defines the desired change, measurement tests whether it occurred, and return keeps investment capital reusable."},
      {id:"ibm_impact_measurement",module:8,source:"IBM-M08-L05",name:"Impact measurement",summary:"Credible impact measurement needs a counterfactual, because a before-and-after comparison can never separate the intervention from selection.",confusions:["A before-and-after increase always proves causation, because the observed change happened after the programme began in the village.","Participants can be compared with any convenient non-participant group, since anyone outside the programme can serve as a control.","Self-selection improves causal confidence, because the most motivated participants change more and therefore show the effect more clearly."],caselet:"A skills programme reports that graduates earn 34% more two years on than a comparison group of non-participants from the same districts. Enrolment was voluntary and required attending an information session, submitting an application and paying a ₹500 deposit. Baseline data show applicants already had 1.9 more years of schooling and were three times likelier to have held formal employment before the programme began. A regional wage boom lifted earnings across all districts over the same period. The funder is being asked to scale the programme fivefold on the strength of the 34% figure.",caseEvidence:"Participants already had 1.9 more years of schooling and were three times likelier to have held formal work before enrolling, so the 34% gap cannot be credited to the programme without a counterfactual separating its effect from selection and the regional wage boom.",application:"Use a comparable control or another defensible counterfactual and account for selection before attributing the income change to the programme.",applicationWrong:["Attribute the full income difference to the loan immediately, without asking what else changed for these households.","Compare the participants with a richer, unrelated village that was never offered the programme.","Use only participant testimonials as causal proof, since the people involved know best what actually changed in their own household finances."],bridge:"A counterfactual separates change caused by the intervention from change that would have happened because of who participated or what else changed."}
    ],
    synthesis: [
      {id:"ibm_syn_access",conceptId:"ibm_aravind",source:"IBM-M02-L08",node:"Access and process",caselet:"A low-cost clinic is near its patients but the only specialist still performs every routine task.",stem:"Which change best joins access with operating capacity?",correct:"Keep the local access model and move standard preparation and follow-up to trained staff so the specialist handles the constrained procedure.",wrong:["Move the clinic back to a premium city location where specialists already prefer to live and work.","Let the price fall by removing quality checks, since affordability is the only barrier these patients actually face.","Increase advertising spend without changing the bottleneck, because more incoming demand will lift the number of procedures each week."],explanation:"Location solves access; task specialisation solves the scarce-capacity constraint.",link:"Inclusive access holds only when the delivery process can serve demand at reliable quality."},
      {id:"ibm_syn_scale",conceptId:"ibm_responsible_lending",source:"IBM-M03-L05",node:"Scale without harm",caselet:"A lender doubles outreach by paying agents per loan while dropping group meetings and total-debt checks.",stem:"What is the central risk?",correct:"Scale has removed the screening and accountability that made lending inclusive, so outreach can become over-indebtedness.",wrong:["The model is safer, because more loans across more lenders always diversify a household's risk.","The only issue is that group meetings reduce the reach of the lender's advertising.","Repayment capacity matters only once a default has actually occurred and losses appear in the book."],explanation:"Inclusive scale must preserve borrower protection and repayment-capacity checks.",link:"Growth that destroys the protective mechanism is not replication of the original model."},
      {id:"ibm_syn_value",conceptId:"ibm_shared_value",source:"IBM-M05-L07",node:"Value and inclusion",caselet:"A buyer's new process cuts its costs but pushes all weather and price risk onto small farmers.",stem:"Why is a shared-value claim weak?",correct:"The firm gained through risk transfer rather than creating additional value that also improves farmer outcomes.",wrong:["Shared value requires the buyer to make no profit on the arrangement at all.","Any supply-chain change is automatically inclusive as long as farmers are involved somewhere in it.","Only donations can benefit farmers, since a commercial relationship always extracts more value than it gives back."],explanation:"Shared value expands value for connected stakeholders instead of extracting it from a weaker one.",link:"Profit and social benefit must arise from the same improved system, not from shifting harm."},
      {id:"ibm_syn_impact",conceptId:"ibm_impact_measurement",source:"IBM-M08-L05",node:"Finance to evidence",caselet:"An impact fund reports how many enterprises it financed but not whether intended social outcomes changed.",stem:"What is missing?",correct:"Outcome measurement against a credible baseline or comparison, not just a count of financial activity.",wrong:["A larger total invested each year, which automatically proves that impact has been achieved.","Removal of the financial-return target, so that the capital counts as philanthropy instead.","A written record of every investor's personal motivation for putting money into the fund in the first place."],explanation:"Money deployed is an input; impact is the change that can reasonably be attributed to the financed activity.",link:"Impact investing becomes accountable when intentional capital is followed by credible outcome evidence."}
    ]
  });

  catalogue.SCLM = makeCourse({
    id:"SCLM",title:"Supply Chain and Logistics Management",shortTitle:"SCLM",description:"How demand, inventory, sourcing, transport, and coordination shape service and cost.",
    modules:["Strategy and performance drivers","Forecasting and planning","Inventory decisions","Sourcing and coordination","Re-engineering the network","Capacity and transport turnaround","Multimodal logistics and ports","Public logistics systems"],
    concepts:[
      {id:"sclm_fit",module:1,source:"SCLM-M01-L04",name:"Strategic fit",summary:"Strategic fit aligns the supply chain's efficiency and responsiveness with the customer promise and its implied uncertainty.",confusions:["Every supply chain should maximise responsiveness regardless of cost, because faster service always wins more customers than price does.","Competitive strategy and supply-chain design can be set independently, since marketing owns the promise and operations owns cost.","Stable demand always means low implied uncertainty, because uncertainty is a property of volume alone."],caselet:"Marketing promises high variety and same-day availability while operations uses slow transport, long batches, and suppliers chosen only for low price.",application:"Redesign the chain for the promised responsiveness or change the promise, because performance always fails when the two diverge.",applicationWrong:["Keep both strategies unchanged, because each function is already locally efficient on its own budget and targets.","Add more product variety and same-day options without changing transport, batch sizes, or supplier selection.","Measure suppliers only on unit purchase price and ignore availability, because the lowest landed cost defines a fit supply chain."],bridge:"The customer promise creates operating requirements; performance fails when the network is built for a different promise."},
      {id:"sclm_drivers",module:1,source:"SCLM-M01-L06",name:"Six supply-chain drivers",summary:"Facilities, inventory, transportation, information, sourcing, and pricing jointly set the balance between responsiveness and efficiency.",confusions:["Transportation speed alone determines supply-chain performance, because every other driver follows the delivery schedule.","Adding facilities always lowers both total cost and total inventory, since local stock is cheaper to hold.","Each driver can be optimised independently, so the best network is the sum of six separate local optima."],caselet:"A quick-commerce firm adds small local fulfilment points and more local stock to reduce delivery time.",application:"Recognise a facilities-and-inventory choice that raises responsiveness while raising fixed cost, since one driver never delivers fit by itself.",applicationWrong:["Treat delivery speed as a free result of branding, since perception rather than network design sets service.","Assume more local facilities reduce every cost line, so their fixed cost needs no separate check.","Ignore information and sourcing because siting stock close to customers guarantees service on its own."],bridge:"Managers deliver strategic fit by configuring several connected drivers, not by maximising one lever in isolation."},
      {id:"sclm_smoothing",module:2,source:"SCLM-M02-L06",name:"Exponential smoothing",summary:"Exponential smoothing updates the old forecast by a fraction alpha of the latest forecast error; a larger alpha reacts more strongly to recent demand.",confusions:["It discards the old forecast entirely and sets the next forecast to the latest actual demand, so history carries no weight.","A larger alpha always produces a smoother and slower response, because alpha measures how much of the old forecast is retained.","The next forecast moves opposite to the latest error, so demand running above forecast pulls the following period's forecast down."],caselet:"Last period's forecast was 100, actual demand was 120, and alpha is 0.25.",application:"Move the next forecast upward by 25% of the 20-unit error, giving 105.",applicationWrong:["Set the next forecast to 120, because the latest actual replaces the old forecast entirely.","Move the forecast down to 95, applying the 25% adjustment against the direction of the error.","Keep it at 100, because smoothing averages past demand and never responds to a single period's error."],bridge:"Forecast error is the signal; alpha controls how quickly planning responds without throwing away accumulated history."},
      {id:"sclm_sop",module:2,source:"SCLM-M02-L12",name:"Sales and operations planning",summary:"S&OP balances forecast demand with capacity, utilisation, inventory, backlog, and outsourcing over a medium-term horizon.",confusions:["It is a daily dispatch schedule for today's orders and makes no capacity or inventory decisions.","A chase plan holds workforce and output constant while inventory absorbs every change in demand.","A level plan changes capacity every period to match demand exactly, hiring and releasing as the forecast moves."],caselet:"A plant with costly hiring and training faces seasonal demand, while its product can be stored economically.",application:"Use a level plan and draw inventory down, since a forecast becomes a decision only when reconciled with capacity cost.",applicationWrong:["Hire and release workers to match each monthly demand change exactly, since matching output to demand avoids holding inventory.","Ignore the forecast until daily orders arrive, because only confirmed orders justify committing capacity.","Absorb the whole peak with backlog even where customers will not tolerate delay, since backlog costs nothing to hold."],bridge:"Forecasts become decisions only when demand is reconciled with the real cost and flexibility of capacity, inventory, and service."},
      {id:"sclm_eoq",module:3,source:"SCLM-M03-L03",name:"Economic order quantity",summary:"EOQ chooses an order size that balances annual ordering cost against holding cost under stable demand, lead time, price, and no-shortage assumptions.",confusions:["EOQ is designed for a single buying opportunity under uncertain seasonal demand, where leftovers are marked down afterwards.","The model assumes frequent planned stockouts and quantity discounts that change the unit price as order size grows.","The largest order the supplier will accept is always optimal, because fewer orders each year always means a lower total annual cost."],caselet:"A component has stable annual demand, fixed cost per order, constant lead time, no discounts, and known annual holding cost.",application:"Use EOQ for the lot size, and never let it answer the separate question of when replenishment must start.",applicationWrong:["Use a newsvendor critical ratio to set the recurring order size, since both models choose a quantity under cost pressure.","Order a full year's demand in one lot, because a single ordering charge always beats twelve smaller ones.","Treat the EOQ quantity as the reorder point itself, so replenishment starts when stock falls to that number."],bridge:"Lot size sets the ordering-versus-holding trade-off; reorder timing answers a different question about when replenishment must start."},
      {id:"sclm_newsvendor",module:3,source:"SCLM-M03-L05",name:"Newsvendor decision",summary:"The newsvendor model chooses a one-time quantity under uncertain demand by balancing the cost of one unit too few against one unit too many.",confusions:["It assumes demand is constant and replenishment repeats indefinitely, so the same quantity is reordered in every cycle of the year.","Only the purchase cost of the item matters here, because salvage value and lost margin sit outside the ordering decision altogether.","Underage and overage costs push the order quantity in the same direction, so raising either of them raises the quantity that should be ordered this season."],caselet:"A seller must choose one order for a short season; leftovers are discounted and unmet demand loses contribution and goodwill.",application:"Use a critical-ratio decision based on underage and overage costs to select the demand quantile.",applicationWrong:["Use EOQ, because the item is inventory and a lot-size formula applies to any stocking decision.","Order the mean forecast quantity regardless of margin and salvage value, since the average is the best single estimate.","Ignore lost margin because only leftover stock carries a visible cost at the end of the season."],bridge:"The economic cost of being short versus long determines which point in the uncertain demand distribution is worth covering."},
      {id:"sclm_portfolio",module:4,source:"SCLM-M04-L04",name:"Tailored sourcing portfolio",summary:"A sourcing portfolio matches responsive sources to volatile, high-value or time-sensitive items and efficient sources to stable, predictable volume while managing disruption risk.",confusions:["One globally cheapest supplier is best for every item, because unit price is the only sourcing dimension that reaches the income statement.","Innovative products with short lives must always be sourced fully offshore, since low labour cost matters most where margins are thin.","Nearshoring removes every cost and disruption trade-off at once, so a closer supplier needs no comparison against a cheaper distant one on total cost."],caselet:"A firm sells one mature high-volume item and one volatile product with short life, high stockout cost, and frequent engineering changes.",application:"Use a low-cost source for stable volume and a faster one for the volatile item, never one cost objective for every item.",applicationWrong:["Place both items with the longest-lead, lowest-price supplier, because a single consolidated relationship simplifies management and maximises volume leverage on unit price.","Reserve the responsive, collaborative source for the stable commodity and leave the volatile item on the slow low-price supplier.","Choose suppliers on landed cost alone, without weighing disruption exposure or the obsolescence risk carried by a short-life product."],bridge:"Different demand and product risks require different source capabilities; a portfolio prevents one cost objective from governing every item."},
      {id:"sclm_bullwhip",module:4,source:"SCLM-M04-L05",name:"Bullwhip effect",summary:"The bullwhip effect is the amplification of order variability upstream even when end-customer demand changes only modestly.",confusions:["It is the fall in transport cost that stable ordering produces once each stage batches its shipments efficiently.","Upstream orders are always less variable than retail sales, because each stage smooths what it passes on.","It occurs only when final consumer demand itself swings sharply, so a stable retail pattern rules the effect out."],caselet:"Retail sales move slightly, but retailer, wholesaler, and manufacturer orders show progressively larger peaks and troughs.",application:"Diagnose amplification across incentives, batching, forecast updates and lead times, since only a shared demand signal stops it.",applicationWrong:["Assume consumer demand moved by the same amount, and read the manufacturer's order swings as a true demand signal.","Ask each stage to optimise its own profit without sharing demand data, since local accountability serves the chain best.","Add more safety stock at every stage without addressing the order distortion that created the swings."],bridge:"Small local reactions compound across stages; coordination and shared demand signals stop defensive decisions from amplifying uncertainty."},
      {id:"sclm_reengineering",module:5,source:"SCLM-M05-L06",name:"Supply-chain re-engineering",summary:"Re-engineering redesigns end-to-end flows to remove hidden time, inventory, hand-offs, and cost while meeting distinct customer service needs.",confusions:["It means cutting one department's budget without examining the stages upstream and downstream of it.","More inventory is the default answer to every service problem, because stock is what protects a customer from delay.","Customer segments should receive identical logistics regardless of need, since one uniform service level is simplest to run and audit."],caselet:"A firm has long queues between stages, excess stock, repeated handling, and customers with very different speed requirements.",application:"Map the full flow, expose waiting and indirect costs, segment service needs, and redesign the connected process rather than one function.",applicationWrong:["Optimise each warehouse separately against its own cost target and leave the upstream effects of those choices unexamined.","Add buffer stock at every hand-off so no stage ever waits, and treat the resulting inventory as the cost of good service.","Give every segment the most expensive service level, since a uniformly high standard cannot disappoint any customer group."],bridge:"Time and inventory hide between organisational boundaries; end-to-end redesign makes those costs and customer trade-offs visible."},
      {id:"sclm_stockyard",module:5,source:"SCLM-M05-L13",name:"Stockyard location trade-off",summary:"Stockyard design balances primary and secondary transport cost, service-distance limits, throughput constraints, and inventory instead of choosing the fewest sites automatically.",confusions:["The geographically central site is always optimal, because the shortest average distance to demand settles the location question.","Primary and secondary movement cost the same per unit moved in every scenario, so only total distance needs minimising.","A location model should ignore minimum viable throughput, because a site's cost per unit does not depend on how much passes through it."],caselet:"Secondary delivery becomes more expensive than primary line-haul and dealers require an overnight service radius.",application:"Re-evaluate site locations using the changed cost structure, coverage limit, demand, and minimum throughput together.",applicationWrong:["Keep the existing sites, because demand locations alone determine where a stockyard belongs.","Consolidate into one large site regardless of dealer distance, since fewer sites always mean lower total network cost.","Minimise primary line-haul distance while leaving secondary delivery cost out of the comparison entirely."],bridge:"A network location changes both legs of transport and facility utilisation; service constraints turn the cheapest map into a feasible operating design."},
      {id:"sclm_coldstore",module:6,source:"SCLM-M06-L05",name:"Cold-storage expansion",summary:"Cold-storage expansion must be judged through seasonal utilisation, commodity flows, operating cost, financing, and market relationships—not capacity alone.",confusions:["A profitable existing site proves any new geography will work, because the operating model travels with the operator.","Debt structure and seasonal demand do not affect expansion risk once the facility is technically sound and well run.","Cold storage earns the same return at every utilisation level, since its costs rise and fall with the volume stored."],caselet:"An efficient operator considers a new city with different commodity flows, trader relationships, seasonal demand, and refrigerated transport needs.",application:"Test local utilisation, commodity fit, economics and financing first, because cold capacity pays only when all of them hold.",applicationWrong:["Copy the current facility exactly, because management skill transfers automatically to any market the operator enters.","Decide from the price of available land alone, treating construction cost as the whole of the expansion question.","Assume the new capacity stays full throughout the year, so a single peak-season utilisation figure can carry the case."],bridge:"An operating capability creates value only when local demand, logistics, and capital structure keep expensive capacity productively used."},
      {id:"sclm_turnaround",module:6,source:"SCLM-M06-L07",name:"Transport turnaround",summary:"Turnaround improves asset throughput by removing waiting from the full trip cycle; Rajashree targeted locomotive detention so the same rakes could make more trips.",confusions:["Throughput can rise only by buying more wagons, since the number of vehicles owned sets the ceiling on annual movement capacity.","Loading speed is the only time that matters in a rail cycle, because a rake starts earning again the moment it is full.","Idle waiting after loading does not affect annual capacity, because the wagons are already loaded and the tonnage has already been committed to a customer."],caselet:"A loaded rake waits an average 13 hours for a locomotive, limiting monthly trips despite adequate loading capacity.",application:"Coordinate an engine-on-load arrangement and accountability for the hand-off so detention falls and trips per rake rise.",applicationWrong:["Buy additional rakes before addressing the 13-hour wait, since more assets must produce more trips.","Increase factory output while loaded wagons continue to stand idle, because production volume is what limits despatch.","Measure only tonnes loaded per wagon and ignore cycle time, since a fuller wagon is always a more productive one."],bridge:"Removing non-value waiting increases the productive cycles of the same asset, linking coordination directly to capacity."},
      {id:"sclm_multimodal",module:7,source:"SCLM-M07-L06",name:"Multimodal cost trade-off",summary:"Mode choice compares end-to-end transport, handling, port, inventory, lot-size, and service effects—not freight rate alone.",confusions:["The lowest line-haul price is always the lowest total logistics cost, because freight dominates every other line.","Large sea lots never create inventory cost, since the goods are paid for only when they are sold.","Handling and first or last-mile legs can be ignored, because both modes incur them equally."],caselet:"Sea freight is far cheaper per tonne than rail but arrives in one very large annual lot and requires port, barge, and inland handling.",application:"Compare movement cost plus inventory and handling before choosing sea, because the freight rate never decides a mode by itself.",applicationWrong:["Choose sea immediately on the line-haul rate per tonne, since the gap against rail is too large to be reversed.","Choose rail because it moves smaller consignments, without costing the inventory that each shipment size creates.","Exclude port, barge, and inland handling from both options, comparing only the long-haul movement between them."],bridge:"A mode changes shipment size, time, handling, and stock as well as freight; total logistics cost joins those consequences."},
      {id:"sclm_ports",module:7,source:"SCLM-M07-L07",name:"Ports and PPP",summary:"Ports support trade and coastal movement; public-private participation can add capacity and operating capability, but performance still depends on connected infrastructure and governance.",confusions:["Port performance is determined only by whether the terminal is publicly or privately owned, and nothing else moves the number.","Container traffic can move at scale without hinterland links, because a terminal's own handling capacity sets its throughput by itself.","Private participation automatically removes every maritime constraint, so oversight of service performance can be withdrawn once the investment arrives and the equipment is installed."],caselet:"A terminal adds modern handling capacity, but road and rail evacuation remain congested and ships still face delays.",application:"Treat terminal investment, hinterland connectivity and service as one system, since capacity pays only when both sides work.",applicationWrong:["Declare the port problem fixed because the cranes are newer than the ones they replaced.","Measure port capability by total national coastline length rather than by cargo actually moved.","Remove performance oversight once private investment is committed, since the operator now carries the commercial risk."],bridge:"A port is a transfer node, so capacity creates trade value only when sea-side operations and inland flows work together."},
      {id:"sclm_leads",module:8,source:"SCLM-M08-L01",name:"LEADS index",summary:"LEADS uses stakeholder perceptions and operating indicators to compare state logistics strengths and improvement areas and encourage policy competition.",confusions:["It is a direct count of warehouse square footage and nothing more, so a state improves its score by building sheds.","It ranks countries rather than Indian states and union territories, so it cannot guide state-level policy.","A high score proves every firm in the state has low logistics cost, since the index measures realised firm outcomes."],caselet:"A state ranks poorly on tracking, infrastructure, regulatory environment, and cargo safety in stakeholder surveys.",application:"Use the dimensions to target state policy, remembering the measure is perception-based and never a guarantee of firm performance.",applicationWrong:["Treat the state's rank as a firm-level profit statement and plan individual company budgets from it.","Improve only warehouse capacity, because infrastructure, regulation, tracking, and cargo safety are not what the index reads.","Ignore the stakeholder evidence entirely, since perception surveys cannot indicate anything about how a state's logistics actually performs."],bridge:"A shared diagnostic makes system weaknesses visible and gives states a basis for coordinated improvement, not a guarantee of firm performance."},
      {id:"sclm_akshaya",module:8,source:"SCLM-M08-L03",name:"Akshaya Patra meal logistics",summary:"Akshaya Patra coordinates menu, mechanised production, labelled containers, route sequencing, vehicles, hygiene, and school time windows as one high-volume service system.",confusions:["Cooking volume alone determines successful meal delivery, because a kitchen that meets its target has met its obligation.","Route labels and loading sequence have no effect on service, since every container eventually holds the same meal for the same schools.","Nutritional standards can be set separately from menu and logistics design, because nutrition is decided before any vehicle is loaded."],caselet:"A central kitchen meets cooking targets, but unlabeled containers and poorly sequenced loading cause late and incorrect school deliveries.",application:"Integrate route packaging, loading order, capacity, meal windows and safety with production, which must all hold end to end.",applicationWrong:["Cook more food without changing dispatch, on the view that shortfalls at school are a production problem.","Remove menu and school identifiers from containers to speed up packing at the kitchen.","Measure success only at the kitchen exit, treating everything after despatch as somebody else's responsibility."],bridge:"Public service quality is completed at the recipient, so production, routing, timing, and safety must hold together end to end."}
    ],
    synthesis:[
      {id:"sclm_syn_fit",conceptId:"sclm_drivers",source:"SCLM-M01-L06",node:"Strategy to drivers",caselet:"A retailer promises low prices and dependable availability but keeps many premium express facilities with duplicated stock.",stem:"Which diagnosis is best?",correct:"Its facilities and inventory choices may be more responsive—and costly—than the competitive promise requires, so the driver configuration lacks strategic fit.",wrong:["More facilities always improve both efficiency and responsiveness at the same time, so the network is already configured correctly for any promise.","Pricing and supply-chain choices are unrelated, because price is set in the market while cost is settled inside operations.","The only useful response is to add more product variety, since a wider range is what a low-price promise needs."],explanation:"Supply-chain drivers should deliver the promised service at the appropriate cost.",link:"Strategy becomes operational through the configuration of facilities, inventory, transport, information, sourcing, and pricing."},
      {id:"sclm_syn_forecast",conceptId:"sclm_sop",source:"SCLM-M02-L12",node:"Forecast to plan",caselet:"A forecast rises sharply, but the plant has long training times and cheap storage.",stem:"What should planning do next?",correct:"Translate the forecast into a capacity-and-inventory plan, likely using stable capacity with inventory and limited flexibility rather than blindly chasing demand.",wrong:["Use the forecast directly as the production order without checking capacity, since the forecast is what the plant has committed to deliver.","Fire and rehire workers each period regardless of training cost, because output should track demand exactly month by month.","Ignore inventory entirely, because forecasting and operations are separate functions that hand work to each other in sequence."],explanation:"S&OP converts forecasts into a feasible, profitable response across operational levers.",link:"A forecast has value only when its uncertainty and timing shape a feasible operating plan."},
      /* A relationship question, not a newsvendor question. Its distractors are
       * EOQ and exponential smoothing, so it tests whether the learner can tell
       * the models apart — a different failure from misapplying the right one.
       * It therefore cites every lecture it discriminates between (which gates
       * it behind all three lessons) and names the prerequisite concepts, so a
       * missed answer here can route back to the relationship rather than to
       * newsvendor alone. */
      {id:"sclm_syn_inventory",conceptId:"sclm_newsvendor",source:"SCLM-M03-L05",sourceIds:["SCLM-M03-L05","SCLM-M03-L03","SCLM-M02-L06"],supportingConceptIds:["sclm_eoq","sclm_smoothing"],node:"Choose the inventory model",caselet:"A fashion item has one buying opportunity, uncertain seasonal demand, and heavy markdowns after the season.",stem:"Which model fits best and why?",correct:"Newsvendor, because a one-time uncertain order turns on shortage and leftover costs.",wrong:["EOQ, because demand is constant across the year and replenishment orders repeat indefinitely.","Exponential smoothing alone, because updating the forecast directly chooses the profit-maximising order quantity.","A Q review model, because replenishment can occur continuously at any point after the season starts."],explanation:"Model choice follows the structure of the decision, not the fact that inventory is involved.",link:"Recurring stable replenishment and one-shot uncertain stocking require different cost logic."},
      {id:"sclm_syn_flow",conceptId:"sclm_turnaround",source:"SCLM-M06-L07",node:"Network flow",caselet:"A network adds stockyards and vehicles, yet orders remain late because loaded assets wait at every organisational hand-off.",stem:"What should be investigated first?",correct:"End-to-end cycle time and hand-off coordination, because idle detention can consume capacity despite more physical assets.",wrong:["Only the purchase price of the new vehicles, since asset cost is what the investment case turns on.","A larger safety-stock target at every node, because more stock at each point protects the delivery promise.","Removal of shared performance measures, so each site is judged only on what it controls directly."],explanation:"Waiting time can be the binding capacity constraint in a network full of assets.",link:"Network design and operating coordination meet in the time an order or asset spends between useful steps."}
    ]
  });

  catalogue.SPMS = makeCourse({
    id:"SPMS",title:"Software Product Management and Strategy",shortTitle:"SPMS",description:"How product teams choose problems, markets, business models, plans, and responsible operating decisions.",
    modules:["Product foundations","Markets and adoption","Positioning and business models","Pricing and unit economics","Competition and communication","Requirements and traceability","Priorities and roadmaps","Metrics and privacy"],
    concepts:[
      {id:"spms_dfv",module:1,source:"SPMS-M01-L05",name:"Desirability, feasibility, viability",summary:"A product opportunity must be wanted by customers, technically achievable, and economically sustainable; strength in only two dimensions leaves a predictable failure.",confusions:["Desirability means that the team can actually engineer the product to the quality standard that the market has come to expect of it.","Viability is proven whenever users say they like an idea, since stated enthusiasm eventually converts into paid revenue at scale over enough time.","A feasible and profitable concept does not need demonstrated customer demand, because the economics on paper already justify the decision to build it."],caselet:"A team can build a device and sell it at a margin, but research shows no meaningful customer problem or willingness to use it.",application:"Treat desirability as the missing test, since a product survives only where all three checks overlap.",applicationWrong:["Launch immediately, because technical feasibility is itself proof that real demand exists.","Reduce the engineering scope even though feasibility has already been established for this particular build.","Call it viable and assume customers will learn to want it once they have seen it working."],bridge:"A product survives only where customer value, engineering reality, and business economics overlap; one cannot compensate indefinitely for another."},
      {id:"spms_jtbd",module:1,source:"SPMS-M01-L10",name:"Jobs to be done",summary:"Jobs to be done always covers functional, emotional and social progress, never merely the product category or the stated feature.",confusions:["The job is the list of features that customers ask developers to copy from a competing product they happen to have already seen somewhere else.","Only the functional task matters, since confidence and social context are irrelevant to whether the customer's job gets done.","A product category defines the same job for every single user, so one category description will cover everyone who sits in that whole market anyway."],caselet:"A patient asks for online consultation but mainly needs quick access to a trusted doctor and confidence that the advice is legitimate.",application:"Design around access, trust and reassurance, because the named feature is never the whole job.",applicationWrong:["Optimise only the video resolution, because that is the feature the customer actually named.","Assume every telehealth user values exactly the same outcome from the consultation they have booked.","Ignore the emotional need entirely, because anything that is not functional cannot be part of the job."],bridge:"Understanding the progress sought reveals which benefits create value and which features are only one possible means."},
      {id:"spms_tamsam",module:2,source:"SPMS-M02-L04",name:"TAM, SAM, and SOM",summary:"TAM, SAM and SOM always narrow in that order: theoretical demand, the servable portion, then the realistic near-term share.",confusions:["SOM is always larger than SAM, because the obtainable market includes every single future market that the firm might eventually decide it wants to enter in future.","TAM is the set of customers that the current sales team expects to win during this quarter from its existing pipeline of qualified leads and nothing more than that.","Regulation, channel, and capability do not affect the serviceable market, since anyone who has the need is theoretically reachable by the product at some point in time."],caselet:"A regulated Indian investing app could theoretically help global investors but can currently serve Indian online retail users and initially targets cost-conscious self-directed investors.",application:"Treat global investors as TAM, Indian online retail investors as SAM, and the reachable cost-conscious segment as SOM.",applicationWrong:["Call the initial segment TAM, because that is the group which will be contacted first in the campaign.","Call all global investors SOM, because a digital product can technically reach any one of them anywhere in the world.","Ignore regulation entirely when defining SAM, since rules do not change who could theoretically buy."],bridge:"Market sizing becomes actionable by narrowing theoretical need through service constraints to the customers the current product can actually win."},
      {id:"spms_chasm",module:2,source:"SPMS-M02-L10",name:"Crossing the chasm",summary:"Crossing to mainstream customers always requires a focused beachhead, a complete experience, references and lower adoption risk.",confusions:["Mainstream adoption follows automatically once innovators approve, because the early verdict carries across to the whole market.","The best strategy is to broaden to every segment at once, before building any references or support structure at all.","Mainstream users tolerate more risk and missing support than early adopters do, since they arrive later and therefore expect a good deal less."],caselet:"A new enterprise tool delights technical pioneers but mainstream buyers ask for uptime, integration, references, security, and support.",application:"Win a narrow beachhead with a complete, credible solution and use its references before expanding.",applicationWrong:["Add more experimental features aimed at every possible segment at the same time.","Dismiss the reliability concerns as ordinary resistance to innovation coming from the more conservative buyers.","Target the whole market at once, before proving that even one repeatable use case works reliably."],bridge:"Early enthusiasm proves possibility; mainstream adoption depends on reducing the practical and social risk of switching."},
      {id:"spms_positioning",module:3,source:"SPMS-M03-L02",name:"Product definition and positioning",summary:"Definition clarifies what is built and why; positioning always states the differentiated value to one target customer against alternatives.",confusions:["A positioning statement is really an internal technical specification, written for the engineering team to build the product from during the development phase itself.","Product definition and positioning are identical feature lists, written out twice over for two different internal audiences to read and then approve before launch.","Positioning does not require naming either a target user or the alternative the product is being compared against by the buyer at the time of purchase."],caselet:"A team describes its payment product only as 'an API with new database tables' when speaking to small merchants.",application:"Translate the internal definition into customer positioning: who it serves, the payment problem solved, the benefit, and why it differs from alternatives.",applicationWrong:["Add more implementation detail into the customer message so the buyer understands exactly how the thing works.","Remove the target segment from the statement so that everyone who reads it feels included in what the product offers.","List the product's features on their own, without ever stating the customer outcome those features are supposed to produce."],bridge:"Definition aligns builders on the solution; positioning helps a chosen customer understand why that solution matters and is different."},
      {id:"spms_lean_canvas",module:3,source:"SPMS-M03-L06",name:"Lean Canvas",summary:"Lean Canvas adapts one-page modelling to early uncertainty, treating every box as an assumption still to be tested.",confusions:["It is used only to document a mature company's fixed operating model once that model has settled.","It removes customer segments and channels from business modelling to keep the single page simple enough to read.","Its purpose is to finalise every assumption before any testing begins with real customers at all."],caselet:"An early startup needs to decide whether a problem is worth solving and which assumptions an MVP should test.",application:"Use Lean Canvas to expose problem, solution, metrics, advantage, segments, channels, costs, and revenue as testable assumptions.",applicationWrong:["Use it as a final audited financial statement for the board to sign off.","Fill only the solution box and treat the rest as execution detail.","Avoid revising the canvas once evidence arrives, since the original plan should be allowed to hold."],bridge:"A compact model makes linked business assumptions visible so learning can change the whole system rather than one feature at a time."},
      {id:"spms_value_pricing",module:4,source:"SPMS-M04-L02",name:"Value-based pricing",summary:"Value-based pricing always starts from measurable customer value and willingness to pay, never from cost or the competitor's price.",confusions:["Price should always equal unit cost plus a fixed markup, whatever the customer actually gains from using it.","All customer segments receive the same value from the product and should therefore be charged an identical price for it.","Value can be priced without ever being articulated or measured, since the customer already knows what it is worth to them anyway."],caselet:"Software saves one segment ₹10 lakh a year but saves another only ₹50,000, while serving both costs roughly the same.",application:"Use the different economic value and willingness to pay to shape segment-specific offers and price structure.",applicationWrong:["Charge both segments from an identical delivery cost, since the software is the same.","Set the price from the cheaper alternative's feature count alone.","Ignore the measurable savings the customer gains, because software has a low marginal cost."],bridge:"Pricing captures part of created value; clear segmentation and value evidence connect customer benefit to business viability."},
      {id:"spms_unit_economics",module:4,source:"SPMS-M04-L07",name:"Unit economics",summary:"Unit economics always tests profitability per customer or transaction: acquisition cost, contribution, lifetime value, churn and payback.",confusions:["Rapid revenue growth proves healthy unit economics automatically, because a fast-growing top line eventually covers everything underneath it in the end.","CAC should be compared with total revenue rather than gross contribution, because revenue is the number the customer actually pays each month.","A long payback period cannot create any cash-flow risk, as long as the lifetime value is high enough to cover it eventually."],caselet:"A subscription spends ₹1,000 to acquire a customer and earns ₹100 monthly gross profit from that customer.",application:"Recognise a ten-month CAC payback before considering retention, cash burn, and whether lifetime gross profit comfortably exceeds acquisition cost.",applicationWrong:["Call the payback period one month, because the subscription happens to bill on a monthly cycle to the customer each time.","Compare CAC only with the top-line company revenue and stop the analysis there without looking at contribution.","Ignore churn entirely, because the acquisition has already happened and that cost is already sunk anyway."],bridge:"Growth consumes cash before contribution repays acquisition; per-unit economics shows whether scaling improves or deepens the problem."},
      {id:"spms_alternatives",module:5,source:"SPMS-M05-L02",name:"Competition and alternatives",summary:"Competition includes every current or potential way customers accomplish the job, including substitutes and doing nothing—not only similar products.",confusions:["Only firms shipping the same feature list should be counted as competitors in this particular market.","Customers cannot compare a product against manual work or against doing nothing about the problem.","Competition should be defined first, before anyone works out the customer's underlying job."],caselet:"A collaboration app compares itself only with two other apps, while prospects continue using email, spreadsheets, meetings, or no formal system.",application:"Evaluate those behaviours as alternatives, because every option competing for the same progress is competition.",applicationWrong:["Ignore them entirely because they are not software products competing in the category.","Study only the companies building on the same technology stack as this product does today.","Assume customers will abandon their current workflows as soon as they see a longer feature list somewhere."],bridge:"The customer's job defines the competitive field; positioning improves when the product beats the real behaviour it must replace."},
      {id:"spms_buyer_journey",module:5,source:"SPMS-M05-L04",name:"Buyer journey communication",summary:"Value communication must always match the buyer's stage: the need, evidence, format and channel useful at that moment.",confusions:["One feature-heavy message should be repeated at every stage of the buyer's journey without change.","Communication begins only after the customer has already purchased, since that is the point at which real support actually starts.","Channel and evidence do not need to match the buyer's questions, because message beats medium."],caselet:"Potential users do not yet recognise a health-monitoring problem, but the campaign opens with a detailed comparison of advanced settings.",application:"First make the problem and relevant value understandable, then introduce alternatives and proof as the buyer advances.",applicationWrong:["Add more technical detail into the very first message the buyer ever receives.","Wait until after the purchase is complete before explaining any of the value to the customer.","Use the same decision-stage proof on audiences who are not yet aware that the problem exists at all."],bridge:"Customers need different information before they can take each next step; timing turns product value into understandable evidence."},
      {id:"spms_requirements",module:6,source:"SPMS-M06-L05",name:"Functional and quality requirements",summary:"Functional requirements state what the product must do and quality requirements how well; a capability is never complete without both.",confusions:["Security and performance are always optional feature requests that can be added later on if there is time.","A functional requirement describes only the colour and layout of the user interface as it finally appears on the screen.","Quality requirements do not need measurable conditions attached to them, since their general intent is already understood by everyone on the team."],caselet:"A login system must authenticate users and block unauthorised access within a defined response time.",application:"Treat authentication as functional, and security and response-time conditions as quality requirements that constrain its implementation.",applicationWrong:["Treat every statement in the list as the same kind of feature label.","Omit the security condition because a login screen already exists somewhere in the product today.","Record response time only after release, not as a requirement."],bridge:"A capability is incomplete without the quality conditions that make it safe, usable, and compliant in the real product."},
      {id:"spms_traceability",module:6,source:"SPMS-M06-L08",name:"Requirements traceability",summary:"Traceability links every customer need through requirement, implementation and verification, so scope and change stay explainable.",confusions:["Traceability is only a list of developer tasks kept inside the team's project tracking tool.","Once a requirement is written down, its original source and its tests can safely be discarded from the record.","Customer requirements and project requirements should never be connected to one another anywhere in the documentation."],caselet:"A team cannot explain which user need a database field supports or which test proves the related requirement works.",application:"Create links from the originating need to the product requirement, implementation item, and verification evidence.",applicationWrong:["Keep each artifact in a separate, unlinked document with no reference between them.","Delete the original customer source once development work has actually started on that requirement.","Approve the field because something like it already exists in code."],bridge:"Traceability preserves the reason behind work, making change impact and completion evidence visible across the development chain."},
      {id:"spms_priority",module:7,source:"SPMS-M07-L01",name:"MoSCoW and RICE prioritisation",summary:"MoSCoW sorts necessity and RICE compares reach, impact, confidence and effort; neither ever replaces judgement.",confusions:["Every stakeholder request should be marked a Must have so that nobody involved is left disappointed.","RICE ignores effort and confidence entirely, and ranks competing ideas on reach and impact alone when scoring them.","A numeric score eliminates the need to examine the assumptions that produced that number in the first place anyway."],caselet:"Two features differ in user reach, likely impact, evidence confidence, and engineering effort, while a legal capability is non-negotiable.",application:"Mark the legal capability as Must and use a transparent RICE comparison for discretionary features, then review assumptions.",applicationWrong:["Put all three items into the Must have category so that no conflict arises between the stakeholders.","Choose the idea with the highest claimed impact and ignore the confidence and effort scores entirely when ranking them.","Let the loudest stakeholder in the room set the order of the whole backlog each time."],bridge:"Prioritisation turns scarce capacity into an explicit decision by separating necessity from comparative value and evidence."},
      {id:"spms_roadmap",module:7,source:"SPMS-M07-L04",name:"Product roadmap",summary:"A roadmap turns strategy into an adaptable sequence of outcomes, always carrying more detail near term than far term.",confusions:["A roadmap is an unchangeable promise of exactly which features will ship, and on exactly which dates, for years into the future.","It is identical to the current sprint backlog, written out in a different format for a different audience each quarter.","Market and technology change should not affect the roadmap, because a plan that keeps moving is not a plan."],caselet:"A team publishes exact five-year feature dates although technology, regulation, and customer evidence are changing quickly.",application:"Keep the direction and outcome sequence, but never present distant work at near-term detail.",applicationWrong:["Freeze every feature date in place in order to protect the credibility of the originally published plan.","Remove the long-term direction altogether and keep only the tasks that the team happens to be working on right now.","Treat the roadmap as a sales contract carrying no uncertainty at all for the customer who has signed it."],bridge:"A roadmap gives direction without pretending distant uncertainty is resolved; learning should reshape the route while strategy anchors it."},
      {id:"spms_metrics",module:8,source:"SPMS-M08-L03",name:"Actionable product metrics",summary:"A useful metric always changes a decision; an impressive total that changes none is only a vanity metric.",confusions:["The largest available number is always the best metric to report, because sheer scale is what demonstrates real progress.","Early-stage products need only the profit measures that a mature company would report to its own board each year.","A metric remains useful even when no action anyone could take would ever change as a result of what that metric reports back."],caselet:"A startup celebrates total registrations while activation, repeat use, churn, acquisition cost, and cash risk remain unclear.",application:"Choose stage-relevant measures tied to decisions, such as activation, retention, contribution, and acquisition payback.",applicationWrong:["Increase the font size of the registration number shown on the dashboard.","Track every possible number without assigning owners or attaching decisions to any single one of them.","Wait for a mature profit history to build up before measuring any product behaviour at all."],bridge:"A metric earns its place when evidence can change resource allocation, product action, or risk response."},
      {id:"spms_privacy",module:8,source:"SPMS-M08-L05",name:"Privacy by design",summary:"Privacy by design makes lawful purpose, consent, minimisation, protection, user rights, and compliant partners part of the product from the start.",confusions:["Privacy is a notice added to the site once the data collection is already complete.","A firm can ignore its partners' data practices entirely once the processing work has been outsourced to them.","All personal data may be reused for any new purpose whenever it improves a feature."],caselet:"An app collects broad personal data for an undefined future use and sends it to an unreviewed analytics vendor.",application:"Limit collection to a stated purpose, establish the lawful basis and user controls, protect the data, and verify the vendor's compliance before transfer.",applicationWrong:["Collect everything available now and decide what the stated purpose for it will be at some later point.","Treat the act of outsourcing as a complete transfer of legal responsibility to the vendor who now holds and processes the data on its behalf.","Rely only on a long terms-of-service page that is published after the collection has already happened on the site."],bridge:"Data value does not remove accountability; product architecture determines whether privacy obligations can actually be honoured."}
    ],
    synthesis:[
      {id:"spms_syn_discovery",conceptId:"spms_jtbd",source:"SPMS-M01-L10",node:"Need to market",caselet:"A team has a technically feasible product for a huge TAM but cannot name the customer progress it improves.",stem:"What should happen before scaling?",correct:"Return to the customer job and desirability evidence, then narrow to a reachable segment whose unmet progress the product can serve.",wrong:["Increase the TAM estimates until the business case finally works on the spreadsheet in front of you.","Add more features to the product, because demonstrated technical feasibility is itself proof of real customer value here.","Set a price for the product before identifying what customer outcome it is actually meant to deliver for anyone who buys it."],explanation:"Market size and technical ability cannot replace a clear customer job and desirability evidence.",link:"Discovery connects the job, the desired value, and the first serviceable market before scale."},
      {id:"spms_syn_model",conceptId:"spms_unit_economics",source:"SPMS-M04-L07",node:"Value to economics",caselet:"Customers report high value and accept the price, but acquisition payback is longer than typical retention.",stem:"What does the evidence imply?",correct:"The offer may create value, but its acquisition or retention economics must change before growth is sustainable.",wrong:["High willingness to pay proves the whole business model is viable on its own.","Increase acquisition spending further, because every additional signup adds revenue straight to the top line each month it renews.","Ignore retention entirely when calculating lifetime value, since that customer has already been won and counted."],explanation:"Customer value and unit economics are separate necessary links in viability.",link:"Pricing captures value, but retention and contribution determine whether acquisition can be repaid."},
      {id:"spms_syn_plan",conceptId:"spms_roadmap",source:"SPMS-M07-L04",node:"Evidence to roadmap",caselet:"A new privacy requirement invalidates a planned data feature, but the roadmap still shows it as committed.",stem:"What is the responsible product response?",correct:"Trace the affected requirement, revise priorities and the roadmap, and communicate how the strategic outcome will be met safely.",wrong:["Build it unchanged, because a published roadmap cannot be moved once it has been committed to publicly.","Delete the privacy requirement from the backlog entirely so that the original delivery date can still be held as promised.","Hide the change from the stakeholders until after the release has already gone out to customers in production."],explanation:"Traceability and an adaptable roadmap let new evidence change delivery without losing strategic direction.",link:"A plan is credible when requirements, priorities, risks, and communication change together."},
      {id:"spms_syn_responsible",conceptId:"spms_privacy",source:"SPMS-M08-L05",node:"Metrics and responsibility",caselet:"A recommendation feature increases engagement but uses sensitive data outside the purpose users accepted.",stem:"Which decision best joins performance and responsibility?",correct:"Stop or redesign the data use, preserve purpose and consent, and measure whether a compliant alternative still delivers customer value.",wrong:["Keep it running, because engagement is the highest product metric the team currently reports to the board.","Update the privacy notice on the site while continuing exactly the same processing underneath it as before the change was made.","Remove the engagement metric from the dashboard altogether so that the issue appears to disappear from view."],explanation:"A performance improvement does not override privacy obligations or user trust.",link:"Responsible product management treats legal and human constraints as part of product value, not as external paperwork."}
    ]
  });

  window.T6_COURSES = catalogue;
})();
